"""Take the last element as the pivot,
     and place that element in the correct sorted position by moving all smaller items to the left of the pivot
     and all larger items to the right of the pivot"""
def partition(arr: Any, low: Any, high: Any) -> object {
    i = low - 1;
    pivot = arr[high];
    for j in range(low, high) {
        if (arr[j] <= pivot) {
            i += 1;
            (arr[i], arr[j]) = (arr[j], arr[i]);
        }
    }
    (arr[(i + 1)], arr[high]) = (arr[high], arr[(i + 1)]);
    return (i + 1);
}

"""This is an example stop condition that asks Relay to quit if
    the error difference between consecutive samples is increasing more than
    half of the time.

    It's quite sensitive and designed for the demo, so you probably shouldn't
    use this is a production setting
    """
def stop_if_mostly_diverging(errdata: Any) -> object {
    n_increases = sum(
        [((abs(y) - abs(x)) > 0) for (x, y) in zip(errdata, errdata[1:])]
    );
    if ((len(errdata) * 0.5) < n_increases) {
        return 0;
    } else {
        return -1;
    }
}

