"""
  Finds the smallest positive integer not in array.
  The smallest possible answer is 1.

  :param array: list of integers
  :return: smallest positive integer not in array.
  """
def solution(array: Any) -> object {
    i = 1;
    visited = [];
    for value in array {
        visited.append(value);
        if (value == i) {
            while True {
                value += 1;
                if (value not in visited) {
                    break;
                }
            }
            i = value;
        }
    }
    return i;
}

"""
    Horizontally flips all angles in the `angles` array.
    """
def flipall_angles(angles: Any) -> object {
    return [(360 - a) for a in angles];
}

"""I need to ensure that NetSurfP is not overwhelmed - so I split the queries to ensure that each is less than Max
	I will use Max = 100000"""
def dont_exceed_max(Max: Any, code_list: Any) -> object {
    C = len(code_list);
    temp_list = [];
    for_inclusion = [];
    limit = 0;
    for i in range(C) {
        (a, b) = code_list[i];
        B = len(b);
        if ((limit + B) < Max) {
            for_inclusion.append(code_list[i]);
            limit += B;
        } else {
            temp_list.append(for_inclusion);
            limit = B;
            for_inclusion = [code_list[i]];
        }
    }
    temp_list.append(for_inclusion);
    return temp_list;
}
